/**
 * Build the map explorer's dataset from the app's own seed files.
 *
 * The site must not carry a second, hand-typed copy of the site list: it would
 * drift from `seed/` within a release, and the whole product argument rests on
 * the record being one thing. So the data is generated, and — like the report
 * PDFs — the generated file is committed, because a deploy that uploads only
 * `landing/` never sees `../seed` at all.
 *
 * English only. `seed/` carries Nepali for every string, but several entries
 * are flagged `ne_review`, and shipping unreviewed translation on the public
 * site is exactly the kind of unsourced claim the project refuses elsewhere.
 */
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const seed = join(here, '..', '..', 'seed');
const out = join(here, '..', 'lib', 'generated', 'explorer.ts');

const read = async (name) => JSON.parse(await readFile(join(seed, name), 'utf8'));

const [sites, timeline, vantages] = await Promise.all([
  read('sites.json'),
  read('timeline.json'),
  read('vantages.json'),
]);

const timelineById = new Map(timeline.map((t) => [t.id, t]));
const vantageCount = vantages.reduce((acc, v) => {
  if (v.active !== false) acc.set(v.site_id, (acc.get(v.site_id) ?? 0) + 1);
  return acc;
}, new Map());

/** Zones group into the two regions the app actually ships. */
const REGION = {
  sacred_garden: 'lumbini',
  monastic_east: 'lumbini',
  monastic_west: 'lumbini',
  greater_lumbini: 'lumbini',
  kathmandu_valley: 'kathmandu',
};

const ZONE_LABEL = {
  sacred_garden: 'Sacred Garden',
  monastic_east: 'East Monastic Zone',
  monastic_west: 'West Monastic Zone',
  greater_lumbini: 'Greater Lumbini',
  kathmandu_valley: 'Kathmandu Valley',
};

/**
 * The first sentence, for the `basic` wisdom tier. Split on a full stop
 * followed by a space and a capital, so "3rd century BCE." and "P. C. Mukherji"
 * do not end the sentence early.
 */
function firstSentence(text) {
  const m = text.match(/^.*?[.!?](?=\s+[A-Z(])/s);
  return (m ? m[0] : text).trim();
}

function period(p) {
  if (!p || p.from == null) return null;
  const era = (y) => (y < 0 ? `${Math.abs(y)} BCE` : `${y} CE`);
  return p.to == null ? `${era(p.from)} to present` : `${era(p.from)} – ${era(p.to)}`;
}

const data = sites.map((s) => ({
  id: s.id,
  name: s.name.en,
  nameNe: s.name.ne ?? null,
  region: REGION[s.zone] ?? 'lumbini',
  zone: ZONE_LABEL[s.zone] ?? s.zone,
  tier: s.tier ?? 3,
  lat: s.coords.lat,
  lon: s.coords.lon,
  /** `osm` is checked against a public gazetteer; `doc` is still approximate. */
  surveyed: s.coords_source === 'osm',
  geofenceM: s.geofence_m ?? null,
  period: period(s.period),
  photography: s.photography ?? null,
  lede: firstSentence(s.summary.en),
  summary: s.summary.en,
  facts: (s.facts ?? []).map((f) => ({ label: f.label.en, value: f.value.en })),
  sources: (s.sources ?? []).map((x) => ({ title: x.title, url: x.url ?? null })),
  passages: s.dhamma_links ?? [],
  vantages: vantageCount.get(s.id) ?? 0,
  timeline: (s.timeline ?? [])
    .map((id) => timelineById.get(id))
    .filter(Boolean)
    .map((t) => ({
      label: t.label.en,
      from: t.year_from,
      to: t.year_to ?? null,
      description: t.description.en,
    }))
    .sort((a, b) => a.from - b.from),
}));

const banner = `// GENERATED by scripts/build-explorer-data.mjs from seed/. Do not edit.
// Regenerate with \`npm run data\` (also runs on predev and prebuild).
`;

await mkdir(dirname(out), { recursive: true });
await writeFile(
  out,
  `${banner}
export type ExplorerFact = { label: string; value: string };
export type ExplorerSource = { title: string; url: string | null };
export type ExplorerEra = { label: string; from: number; to: number | null; description: string };

export type ExplorerSite = {
  id: string;
  name: string;
  nameNe: string | null;
  region: 'lumbini' | 'kathmandu';
  zone: string;
  tier: number;
  lat: number;
  lon: number;
  surveyed: boolean;
  geofenceM: number | null;
  period: string | null;
  photography: string | null;
  lede: string;
  summary: string;
  facts: ExplorerFact[];
  sources: ExplorerSource[];
  passages: string[];
  vantages: number;
  timeline: ExplorerEra[];
};

export const SITES: ExplorerSite[] = ${JSON.stringify(data, null, 2)};
`,
  'utf8',
);

console.log(`[explorer-data] ${data.length} sites -> lib/generated/explorer.ts`);
